-- Fills footprint_json and height for every campus location, then makes
-- both columns NOT NULL so no row can be left without them again.
--
-- Where the values come from (generated 2026-09-30):
--   footprint_json  OpenStreetMap outline of the building/area at the pin.
--                   Gates (and anything with no mapped area) get a 4 m square
--                   around the pin.
--   height          Mapbox's own building height at the pin, so it matches
--                   the 3D building the map already draws. 0 for anything
--                   that isn't a building.
--   height_override true only where the height was corrected by hand - the
--                   map draws its own 3D block for those rows (Henry Sy).
--
-- Storage rooms and venues copy the footprint and height of the facility
-- they're inside.

BEGIN;

ALTER TABLE tbl_campus_facilities ADD COLUMN IF NOT EXISTS height_override boolean NOT NULL DEFAULT false;

