FROM tbl_campus_facilities f WHERE f.campus_facility_id = v.campus_facility_id;

ALTER TABLE tbl_campus_facilities ALTER COLUMN height SET NOT NULL, ALTER COLUMN footprint_json SET NOT NULL;
